// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows, material = {}) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated, points, acceptedAnswers}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    if (acceptedAnswers && (!acceptedAnswers.includes(answer) || new Set(acceptedAnswers).size !== acceptedAnswers.length ||
        !acceptedAnswers.every(index => Number.isInteger(index) && index >= 0 && index < choices.length))) {
      throw new Error('Invalid accepted answers in ' + year + '/' + grade + '/' + (index + 1));
    }
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, detailSrc, description, pixelWidth, pixelHeight}, i) => ({
      image: src, ...(detailSrc ? {detailSrc} : {}), description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(acceptedAnswers ? {acceptedAnswers} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: points ?? (index < 10 ? 3 : index < 20 ? 4 : 5),
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const tokens = step === 3 ? (lessons[i].acceptedAnswers ?? [letters.indexOf(key)]).map(index => {
        const result = lessons[i].choices[index].replace(/^\[(.*)\][.]?$/, '$1');
        return letters[index] + (result ? ' · ' + result : '');
      }) : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы'),
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + (material.tasksFile ?? grade + '.pdf'),
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (reviewedKey ? 'reviewed-' + grade + '.pdf' : material.answersFile ?? grade + '-answers.pdf'),
      ...(material.solutionsFile ? {solutionUrl: 'assets/medvezhonok/' + year + '/' + material.solutionsFile} : {}),
      ...(year === 2004 && grade === '2-3' ? {solutionUrl: 'assets/medvezhonok/2004/2-3-answers.pdf'} : {}),
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2000, "5-6", [{"author":"Учителя ФМШ 146 г. Перми","question":"Сколько букв в русском алфавите?","choices":["26","30","32","33","43"],"key":"Г","review":["Число букв алфавита","В русском алфавите десять гласных букв, двадцать одна согласная и два знака.","Складываем 10, 21 и 2. Получается 33."]},{"author":"М. Кронгауз","question":"Сколько из перечисленных действий совершает комар: кусает, летает, сосёт, чешет, чихает?","choices":["одно","два","три","четыре","все"],"key":"В","review":["Что делает комар","Комары летают. Комар, который прокалывает кожу, кусает и сосёт кровь.","Чешется место укуса, а не сам комар. Чихание тоже не относится к нему. Всего три действия."]},{"author":"Е. Муравенко","question":"Из слова ворот выбрать три подряд идущих буквы так, чтобы получилось существительное русского языка, можно двумя разными способами: ВОРот и воРОТ. А сколькими разными способами можно так выбрать три подряд идущих буквы из слова колобок?","choices":["0","1","2","3","4"],"key":"Г","review":["Три соседние буквы","Последовательно выдели в слове «колобок» группы по три буквы: «кол», «оло», «лоб», «обо», «бок».","Обычные существительные среди них — «кол», «лоб» и «бок». Получается три способа."]},{"author":"М. Кронгауз","question":"Сколько из перечисленных слов являются названиями профессий: читатель, учитель, самоучитель, строитель, писатель?","choices":["одно","два","три","четыре","все"],"key":"В","review":["Профессия или вид занятия","Учитель, строитель и писатель — названия профессий.","Читателем может быть любой, кто читает. Самоучитель — книга или другое пособие для самостоятельного обучения. Профессий три."]},{"author":"Е. Муравенко","question":"Какие из приведённых слов являются однокоренными со словом вода: 1) водить, 2) водяной, 3) завод, 4) водичка, 5) водный?","choices":["2, 4, 5","3, 4","1, 4","2, 4","все"],"key":"А","review":["Корень со значением воды","Водяной, водичка и водный сохраняют значение воды и общий с «вода» корень.","«Водить» связано с движением или управлением, а «завод» называет предприятие. Подходят 2, 4 и 5."]},{"author":"Е. Муравенко","question":"Отметьте из приведённых ниже слов слова с одинаковыми приставками: 1) отмерять, 2) отравить, 3) отвар, 4) отчизна.","choices":["1, 2","1, 3","1, 2, 3","2, 3","1, 2, 3, 4"],"key":"Б","review":["Граница приставки и корня","В «отмерять» и «отвар» выделяется от-. Это видно при сравнении с «мерять» и «варить».","«Отравить» делится на о- и -трав-, «отчизна» связана со словом «отец». Их первые буквы принадлежат другим частям слова."]},{"author":"М. Кронгауз","question":"Какие из перечисленных названий животных используются для обозначения большого и неуклюжего человека: баран, корова, медведь, слон?","choices":["все","баран, корова, медведь","баран, корова, слон","баран, медведь, слон","корова, медведь, слон"],"key":"Д","review":["Животные как сравнение","Крупного неуклюжего человека по сходству называют медведем или слоном. О неуклюжем человеке также говорят «корова».","Слово «баран» в переносном смысле чаще подчёркивает упрямство или непонятливость. Поэтому оно не подходит."],"reviewedEdition":true},{"author":"Е. Муравенко","question":"Слово сковорода рассыпали на буквы. Из этих букв сложили два других слова так, что неиспользованных букв не осталось. Какими могли быть эти слова?","choices":["сок + борода","совок + орда","сова + город","дрова + коса","воск + колода"],"key":"Б","review":["Используем все буквы","В «сковороде» три о, а остальные буквы — с, к, в, р, д, а — встречаются по одному разу.","В сочетании «совок + орда» сохраняется этот состав. В остальных вариантах хотя бы одна буква заменена."]},{"author":"М. Кронгауз","question":"Можно сказать, что слово полочка образовано от слова полка и может иметь значение «маленькая полка» или «полка маленького размера». Возьмём слова бухта, водка, кофта, минута, поляна и образуем от них слова бухточка, водочка, кофточка, минуточка, поляночка. Сколько из этих слов могут означать соответствующий предмет маленького размера?","choices":["1","2","3","4","5"],"key":"В","review":["Маленький предмет","Бухточкой, кофточкой и поляночкой можно назвать маленькую бухту, кофту и поляну.","Водка — напиток, минута — отрезок времени. «Водочка» и «минуточка» имеют уменьшительную окраску, но не обозначают предметы маленького размера. Подходят три слова."]},{"author":"К. Кноп","question":"Как называется короткая смешная история?","choices":["анегдот","анекдот","анигдот","аникдот","среди вариантов (А)–(Г) нет правильного"],"key":"Б","review":["Правописание слова","Короткий смешной рассказ называют «анекдот».","Пишется ане-, а перед д стоит к, хотя на слух там можно принять согласную за г."]},{"author":"И. Рубанов","question":"Вспомните родственные слова и скажите, из скольких лошадей состояла упряжка, которую римляне называли квадригой.","choices":["из трёх","из четырёх","из пяти","из шести","из семи"],"key":"Б","review":["Сколько коней в квадриге","Начало «квадри-» связано с латинским обозначением четырёх. Сравни «квадрат» с его четырьмя сторонами.","Квадрига — колесница, запряжённая четырьмя лошадьми. Это вариант Б."]},{"author":"Е. Муравенко","question":"Сколько в данном списке слов с суффиксом -чик: ключик, стульчик, мячик, перчик, карманчик?","choices":["1","2","3","4","5"],"key":"Б","review":["Одинаковые звуки, разные части","«Стульчик» и «карманчик» образованы от «стул» и «карман» прибавлением -чик.","В «ключик» и «мячик» ч уже есть в корне, а в «перчик» оно сменяет ц слова «перец». Там суффикс -ик. С суффиксом -чик два слова."]},{"author":"Е. Муравенко","question":"В старой орфографии (до 1918 г.) на месте современного и использовались две буквы: и и і, например: піанист, ближній, зданіе, милліон, Марія. Как записывались в старой орфографии слова июнь, синий?","choices":["іюнь, синій","июнь, синій","іюнь, синий","іюнь, сіній","іюнь, сіний"],"key":"А","review":["Две старые буквы","По примерам видно, что і писали перед гласными и перед й. Перед согласными оставляли и.","В «іюнь» первая буква перед ю, а в «синій» вторая и стоит перед й. Верна первая пара написаний."]},{"author":"Е. Муравенко","question":"В скольких существительных из данного списка произойдут изменения в склонении, если ударение с первого слога перенести на второй: белки, замки, трусы, полы, кружки?","choices":["1","2","3","4","5"],"key":"Г","review":["Ударение и падеж","«Бе́лки» и «белки́» дают «белок» и «белков». «Тру́сы» и «трусы́» различаются в винительном: «вижу трусов» и «вижу трусы».","У «по́лы — полы́» в родительном падеже «пол — полов», у «кру́жки — кружки́» — «кружек — кружков». Формы «за́мков — замко́в» различаются только ударением. Подходят четыре слова."]},{"author":"М. Кронгауз","question":"Сколько из перечисленных слов сочетаются и со словом маленький, и со словом маленькая: грязнуля, зануда, плакса, тупица, красавица?","choices":["1","2","3","4","5"],"key":"Г","review":["Маленький и маленькая","Грязнулей, занудой, плаксой и тупицей могут назвать как мальчика, так и девочку.","«Красавица» относится к женскому роду. Подходят четыре слова."],"reviewedEdition":true},{"author":"К. Кноп","question":"Посмотрите на список слов: м...тель, кр...хтеть, за...ц, м...теж. В скольких из них пропущена буква я (а не е)?","choices":["0","1","2","3","4"],"key":"Г","review":["Я или е в четырёх словах","Пишется «метель», «кряхтеть», «заяц», «мятеж».","Я нужна в трёх словах: «кряхтеть», «заяц» и «мятеж»."]},{"author":"К. Кноп","question":"В одной детской книжке описывается «конспиративный язык», на котором между собой общаются мальчишки. Вот пример правильной фразы на этом языке: «Шара-вчеца шаяца шанаца шажин-уца шасъелца шашу-каца шаица шапил-выца шаю-чаца». Переведите на этот язык слово залив.","choices":["шазаливца","шаив-залца","шалив-заца","шаза-ливца","среди вариантов (А)–(Г) нет правильного"],"key":"В","review":["Язык мальчишек","В примере к слову добавляют «ша» в начале и «ца» в конце. Внутри многосложного слова части меняются местами, как «вче-ра» → «ра-вче».","«За-лив» превращается в «лив-за». С добавками выходит «шалив-заца»."]},{"author":"Е. Муравенко","question":"Прочтите загадку, зашифрованную в ребусе, и найдите подходящую отгадку.","choices":["ножницы","игла","молоток","метла","пила"],"key":"А","review":["Загадка из двух строк","Читаем начало ребуса как «два», «конь» без ь и «лица» без первых двух букв. Получается «два конца».","Дальше загадка описывает два кольца и крепление посередине. Так устроены ножницы."],"figure":{"condition":{"src":"assets/medvezhonok/2000/5-6-18-rebus.webp","alt":"Ребус в две строки. Используются буквы внутри букв, конь, три лица, нота на нотном стане, огурец, единица и цветок. Запятые указывают, где нужно отбросить буквы.","width":780,"height":339}}},{"author":"Е. Муравенко","question":"Найдите синоним устойчивого словосочетания попасть впросак.","choices":["сесть в калошу","отбиться от рук","заблудиться в трёх соснах","повесить нос","уйти в свою скорлупу"],"key":"А","review":["Два оборота о неудаче","«Попасть впросак» — оказаться в неловком положении, обычно из-за собственной ошибки.","«Сесть в калошу» означает осрамиться и передаёт тот же смысл."]},{"author":"Е. Муравенко","question":"Какое из пяти перечисленных слов по смыслу лишнее?","choices":["шведка","болгарка","итальянка","японка","корейка"],"key":"Д","review":["Национальности и продукт","Шведка, болгарка, итальянка и японка называют жительниц или представительниц народов.","Корейка — часть мясной туши или продукт из неё. Жительницу Кореи называют «кореянка»."]},{"author":"М. Кронгауз","question":"Какое из пяти перечисленных слов по смыслу лишнее?","choices":["обезьяна","зайчиха","львица","актриса","японка"],"key":"А","review":["Название самки или женщины","Зайчиха, львица, актриса и японка указывают на женский пол. У них есть пары «заяц», «лев», «актёр», «японец».","Слово «обезьяна» может обозначать животное любого пола. Оно отличается по смыслу."]},{"author":"Е. Муравенко","question":"Сколько слов из данного списка можно понять и как существительное, и как глагол: шила, мыла, выла, дела, жили, были, рыли, жил?","choices":["2","3","4","5","6"],"key":"Г","review":["Две части речи в одной форме","«Шила» может быть формой слов «шить» и «шило», «мыла» — «мыть» и «мыло», «дела» — «деть» и «дело».","«Были» бывают рассказами и формой «быть», «жил» — формой «жила» и «жить». Получается пять слов."],"reviewedEdition":true},{"author":"Е. Муравенко","question":"В скольких словах из данного списка букву е можно читать и как е, и как ё: вел, мел, сел, осел, дел?","choices":["1","2","3","4","5"],"key":"В","review":["Е и ё меняют значение","«Мел — мёл» даёт название вещества и глагол, «сел — сёл» — глагол и форму слова «село».","«Осе́л — осёл» даёт ещё пару. Для «вел» в этом ряду подходит только «вёл», а «дел» читается с е. Всего три."]},{"author":"Е. Муравенко","question":"Образуйте форму 1 лица единственного числа от глагола убедить.","choices":["убедю","убежду","убежу","убеждаю","форма не образуется"],"key":"Д","review":["Недостающая глагольная форма","У глагола «убедить» нет нормативной формы первого лица единственного числа: «убедю», «убежу» и «убежду» не подходят.","«Убеждаю» — форма другого глагола, «убеждать». Можно сказать «смогу убедить»."]},{"author":"Е. Муравенко","question":"Попробуем читать звуки, из которых состоят слова лён, сад, луг, люк, альт, в обратном порядке. Сколько новых слов получится?","choices":["5","4","3","2","1"],"key":"Б","review":["Обратный порядок звуков","«Лён» [л’он] даёт «ноль» [нол’], «сад» [сат] даёт «таз» [тас], «люк» [л’ук] даёт «куль» [кул’].","«Альт» [ал’т] даёт «тля» [тл’а]. Из «луг» [лук] выходит [кул], обычного русского слова с таким произношением нет. Получаются четыре."]},{"author":"Е. Муравенко","question":"Сколько существительных женского рода представлено в списке: туфли, ботинки, овощи, тюль, вуаль, рояль?","choices":["0","1","2","3","4"],"key":"В","review":["Род по единственному числу","От «туфли» образуется «туфля», слово женского рода. «Вуаль» тоже женского рода: «тонкая вуаль».","Ботинок, овощ, тюль и рояль — мужского рода. Женских два."]},{"author":"И. Рубанов","question":"Вспомните старинное название одной из русских букв и скажите, каков буквальный смысл выражения ходить фертом.","choices":["ходить, сгорбившись","ходить, уперев руки в бока","ходить с гордо поднятой головой","ходить вразвалку","ученые до сих пор об этом спорят"],"key":"Б","review":["Поза в форме буквы","«Ферт» — старинное название буквы Ф. У буквы вертикальная стойка и две округлые стороны.","Если упереть руки в бока, фигура станет похожа на Ф. Таков буквальный образ выражения."]},{"author":"М. Кронгауз","question":"Сколько из перечисленных слов обозначают домашнее животное: верблюд, корова, крокодил, дикая крыса, собака?","choices":["одно","два","три","четыре","все"],"key":"В","review":["Животные рядом с человеком","К домашним животным относятся корова, собака и одомашненный верблюд, на котором ездят и перевозят грузы.","Крокодил и дикая крыса к домашним животным не относятся. Подходят три названия."],"reviewedEdition":true,"keyNote":"В исходном перечне стояло просто «крыса». Поскольку существует одомашненная декоративная крыса, в условии уточнено «дикая крыса». Буква В сохранена."},{"author":"Е. Муравенко","question":"Сколькими способами можно в ряду букв ПОДНИМИТЕПЕРЬЯ расставить пробелы (не вставляя никаких знаков препинания), чтобы получилась фраза?","choices":["2","3","4","5","6"],"key":"Д","review":["Шесть границ слов","Начать можно повелением «поднимите перья» или «подними те перья».","Ещё четыре фразы: «под ними те перья», «под ним и те перья», «под ними теперь я», «под ним и теперь я». Все шесть используют те же буквы."]},{"author":"Я. Миронов","question":"Постарайтесь понять, по какому принципу составлена «смысловая пропорция»\nсилён : слабее = мягок : X = твёрд : Y = Z : глуше,\nи ответьте, какие три слова зашифрованы буквами X, Y и Z:","choices":["мягчее, твёрже, глух","твёрже, мягче, звóнок","твердее, мягче, ярче","мягче, твёрже, звонче","ни один из вариантов (А)–(Г) не верен"],"key":"Б","review":["Сравнение с противоположностью","После «силён» стоит сравнительная степень противоположного признака: «слабее». Так же «мягок — твёрже», «твёрд — мягче».","Для «глуше» исходный противоположный признак — «зво́нок». Три слова даёт вариант Б."],"reviewedEdition":true}], {"year":2000,"grade":"5-6","tasksFile":"5-6.pdf","answersFile":"5-6-answers.pdf","sourceUrl":"https://konkurs43.ru/rm/task2000.zip"}), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
